#include <string>
#include <vector>

std::vector<float> rightAlignedX(const std::vector<std::string>& labels, float charWidth, float framePadding,
                                 float spacing, float contentMaxX, float contentMinX)
{
    std::vector<float> widths;
    float total{ 0.0f };
    for (std::size_t i{ 0 }; i < labels.size(); ++i)
    {
        const float w{ static_cast<float>(labels[i].size()) * charWidth + 2.0f * framePadding };
        widths.push_back(w);
        total += w + (i ? spacing : 0.0f);
    }
    float x{ contentMaxX - total };
    if (x < contentMinX) x = contentMinX;
    std::vector<float> out;
    for (float w : widths)
    {
        out.push_back(x);
        x += w + spacing;
    }
    return out;
}

unitTests:
TEST("the example") { CHECK_EQ(rightAlignedX({ "Cancel", "OK" }, 7, 4, 8, 400, 10), (std::vector<float>{ 320, 378 })); }
TEST("three buttons") { CHECK_EQ(rightAlignedX({ "Cancel", "Apply", "OK" }, 10, 5, 4, 500, 0), (std::vector<float>{ 332, 406, 470 })); }
TEST("does not fit") { CHECK_EQ(rightAlignedX({ "A very long label", "OK" }, 10, 5, 4, 100, 20), (std::vector<float>{ 20, 204 })); }
TEST("one button") { CHECK_EQ(rightAlignedX({ "OK" }, 8, 4, 8, 200, 0), (std::vector<float>{ 176 })); }
TEST("no buttons") { CHECK(rightAlignedX({}, 8, 4, 8, 200, 0).empty()); }

